import math

def sigmoid(x): return 1 / (1 + math.exp(-x))
def tanh(x):    return math.tanh(x)
def relu(x):    return max(0.0, x)
def lrelu(x, a=0.01): return x if x > 0 else a * x

def softmax(v):
    ev = [math.exp(x) for x in v]
    s = sum(ev)
    return [round(e / s, 4) for e in ev]

for x in [-2.0, 0.0, 2.0]:
    print(f"x={x:5.1f}  sig={sigmoid(x):.4f}  tanh={tanh(x):.4f}  relu={relu(x):.1f}")

print(softmax([1.0, 2.0, 3.0]))
